function urbanoStyle(feature) {
    return {
        color: '#FF4500',
        weight: 3,
        opacity: 0.9,
        dashArray: '8, 6'
    };
}

var urbanoLayer = L.geoJson(urbano, {
    style: urbanoStyle,
    attribution: 'urbanochosma.wordpress.com',
    onEachFeature: onEachFeature
});

// Controles
L.control.layers({
    'Open Street Map': osm,
    'Satelital': Esri_WorldImagery
}, {
    'Barrios': capaBarrios,
    'Área edificada': areaEdificadaLayer,
    'Densidad poblacional': densityLayer,
    'Turismo': turismoLayer,
    'Transporte urbano': urbanoLayer
    
}, {
    position: 'topleft',
    collapsed: true
}).addTo(mimapa);

L.control.scale({
    metric: true,       // Muestra metros/kilómetros
    imperial: false,    // Desactiva pies/millas (opcional)
    position: 'bottomleft'
}).addTo(mimapa);






